-- Admin-editable D2 identity policy: one row holding the whole rule set as JSON.
-- The seed is INSERT OR IGNORE so a restart never overwrites an admin edit; it
-- must stay identical to modelidentity.InitialRules (TestPolicySeedMatchesInitialRules).
CREATE TABLE IF NOT EXISTS model_identity_policy (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    revision INTEGER NOT NULL CHECK (revision >= 1),
    rules TEXT NOT NULL
);

INSERT OR IGNORE INTO model_identity_policy (id, revision, rules) VALUES (1, 1, '[{"providers":["anthropic"],"tier":"opus","pattern":"claude-opus-(\\d{1,3})(?:-(\\d{1,3}))?","version_groups":[1,2]},{"providers":["anthropic"],"tier":"sonnet","pattern":"claude-sonnet-(\\d{1,3})(?:-(\\d{1,3}))?","version_groups":[1,2]},{"providers":["anthropic"],"tier":"haiku","pattern":"claude-haiku-(\\d{1,3})(?:-(\\d{1,3}))?","version_groups":[1,2]},{"providers":["anthropic"],"tier":"fable","pattern":"claude-fable-(\\d{1,3})(?:-(\\d{1,3}))?","version_groups":[1,2]},{"providers":["openai"],"tier":"sol","pattern":"gpt-(\\d+(?:\\.\\d+)?)-sol","version_groups":[1]},{"providers":["openai"],"tier":"astra","pattern":"gpt-(\\d+(?:\\.\\d+)?)-astra","version_groups":[1]},{"providers":["openai"],"tier":"luna","pattern":"gpt-(\\d+(?:\\.\\d+)?)-luna","version_groups":[1]},{"providers":["openai"],"tier":"terra","pattern":"gpt-(\\d+(?:\\.\\d+)?)-terra","version_groups":[1]},{"providers":["deepseek","ollama-cloud","openrouter"],"tier":"flash","pattern":"deepseek-v(\\d+(?:\\.\\d+)?)-flash","version_groups":[1]},{"providers":["deepseek","ollama-cloud","openrouter"],"tier":"pro","pattern":"deepseek-v(\\d+(?:\\.\\d+)?)-pro","version_groups":[1]},{"providers":["zhipuai","ollama-cloud"],"tier":"glm","pattern":"glm-(\\d+(?:\\.\\d+)?)","version_groups":[1]},{"providers":["zhipuai","ollama-cloud"],"tier":"glm-flash","pattern":"glm-(\\d+(?:\\.\\d+)?)-flash","version_groups":[1]},{"providers":["moonshotai","ollama-cloud"],"tier":"kimi","pattern":"kimi-k(\\d+(?:\\.\\d+)?)","version_groups":[1]},{"providers":["moonshotai","ollama-cloud"],"tier":"kimi-code","pattern":"kimi-k(\\d+(?:\\.\\d+)?)-code","version_groups":[1]}]');
